package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_getTextBuffer_TriageGen0Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }

    @Test
    public void testGetTextBuffer_SharedInputBuffer() {
        char[] sharedBuf = new char[]{'a', 'b', 'c'};
        // resetWithShared sets _inputStart >= 0
        textBuffer.resetWithShared(sharedBuf, 0, 3);

        char[] result = textBuffer.getTextBuffer();

        assertSame("Should return the shared input buffer", sharedBuf, result);
    }

    @Test
    public void testGetTextBuffer_ResultArray() {
        // To trigger the second condition (_resultArray != null), 
        // we use resetWithCopy which populates the internal result array.
        char[] input = {'h', 'e', 'l', 'l', 'o'};
        textBuffer.resetWithCopy(input, 0, 5);

        // Manually trigger a state where _resultArray is set but _inputStart is -1
        // resetWithCopy typically ensures _inputStart is -1 and populates _resultArray
        char[] result = textBuffer.getTextBuffer();

        assertNotNull(result);
        assertEquals("hello", new String(result));
    }

    @Test
    public void testGetTextBuffer_ResultString() {
        // To trigger the third condition (_resultString != null),
        // we use resetWithString.
        String input = "test";
        textBuffer.resetWithString(input);

        // Note: resetWithString sets _resultString. 
        // The first two conditions must be false.
        char[] result = textBuffer.getTextBuffer();

        assertNotNull(result);
        assertEquals("test", new String(result));
        // Verify that _resultArray was lazily initialized
        // Calling it again should return the same array (second condition)
        char[] secondResult = textBuffer.getTextBuffer();
        assertSame(result, secondResult);
    }

    @Test
    public void testGetTextBuffer_SingleSegment() {
        // To trigger the fourth condition (!_hasSegments),
        // we use the buffer in its fresh state or after resetWithEmpty.
        textBuffer.resetWithEmpty();

        // In a fresh state, _inputStart is -1, _resultArray is null, _resultString is null, 
        // and _hasSegments is false.
        char[] result = textBuffer.getTextBuffer();

        assertNotNull(result);
        // Should return the current segment (the internal buffer)
        assertSame("Should return the current segment", textBuffer.getCurrentSegment(), result);
    }

    @Test
    public void testGetTextBuffer_MultiSegments() {
        // To trigger the fifth condition (contentsAsArray()),
        // we need to force the buffer to have multiple segments.
        textBuffer.resetWithEmpty();

        // Fill the first segment and force a new one
        char[] largeChunk = new char[textBuffer.getCurrentSegmentSize()];
        for(int i=0; i < largeChunk.length; i++) largeChunk[i] = 'a';

        textBuffer.append(largeChunk, 0, largeChunk.length);
        textBuffer.finishCurrentSegment();

        // Now _hasSegments is true
        textBuffer.append('b');

        char[] result = textBuffer.getTextBuffer();

        assertNotNull(result);
        // Since it's segmented, it should return a consolidated array via contentsAsArray()
        assertEquals("ab", textBuffer.contentsAsString());
        // The length of the result should match the content length
        assertEquals(2, result.length);
        assertEquals('a', result[0]);
        assertEquals('b', result[1]);
    }
}
